import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';

const stateDirectory = new URL('../target/', import.meta.url);
const stateFile = new URL('ticket-state', stateDirectory);
const transitions = {
  draft: { open: 'open' },
  open: { close: 'closed' },
  closed: { reopen: 'open' },
};

let state = 'draft';

try {
  state = readFileSync(stateFile, 'utf8').trim();
} catch (error) {
  if (error.code !== 'ENOENT') {
    throw error;
  }
}

if (!Object.hasOwn(transitions, state)) {
  throw new Error(`Invalid stored ticket state: ${JSON.stringify(state)}`);
}

const action = process.argv[2];

if (action === undefined) {
  console.log(state);
} else {
  const nextState = transitions[state][action];

  if (nextState === undefined) {
    console.error(`Cannot ${action} ticket from ${state}`);
    process.exitCode = 1;
  } else {
    mkdirSync(stateDirectory, { recursive: true });
    writeFileSync(stateFile, `${nextState}\n`, 'utf8');
    console.log(nextState);
  }
}

